#pragma region AST Printer

static const char *op_to_str(token_type_t op_token) {
  switch (op_token) {
  case TOK_UNARY_PLUS:
    return "+ (unary)";
  case TOK_BINARY_PLUS:
    return "+";
  case TOK_UNARY_MINUS:
    return "- (unary)";
  case TOK_BINARY_MINUS:
    return "-";
  case TOK_MUL:
    return "*";
  case TOK_DIV:
    return "/";
  case TOK_LOWER_T:
    return "<";
  case TOK_LOWER_EQ:
    return "<=";
  case TOK_GREATER_T:
    return ">";
  case TOK_GREATER_EQ:
    return ">=";
  case TOK_EQUAL:
    return "==";
  case TOK_NOT_EQ:
    return "!=";
  case TOK_ASSIGN:
    return "=";
  case TOK_AND:
    return "&&";
  case TOK_OR:
    return "||";
  case TOK_NOT:
    return "!";
  case TOK_CONCAT_LIST:
    return "++";
  default:
    return "?";
  }
}

static std::string format_type(data_type_node_t *dt_node) {
  if (dt_node == nullptr) {
    return "null";
  }
  switch (dt_node->type) {
  case DATA_TYPE_PRIMITIVE:
    switch (dt_node->data.primitive_type) {
    case PRIMITIVE_INT:
      return "Int";
    case PRIMITIVE_DOUBLE:
      return "Double";
    case PRIMITIVE_STRING:
      return "String";
    case PRIMITIVE_BOOLEAN:
      return "Boolean";
    }
    break;
  case DATA_TYPE_UNIT:
    return "Unit";
  case DATA_TYPE_ANY:
    return "Any";
  case DATA_TYPE_RANGE:
    return "Range";
  case DATA_TYPE_CLASS:
    return (dt_node->data.class_type.name != nullptr)
               ? dt_node->data.class_type.name
               : "Class";
  case DATA_TYPE_GENERIC:
    return (dt_node->data.generic_type.name != nullptr)
               ? dt_node->data.generic_type.name
               : "Generic";
  case DATA_TYPE_LIST:
    return "List[" + format_type(dt_node->data.list_type.elements_type) + "]";
  case DATA_TYPE_UNION: {
    std::string res;
    for (data_type_node_t *curr = dt_node->data.union_type.types;
         curr != nullptr; curr = curr->next) {
      if (!res.empty()) {
        res += " | ";
      }
      res += format_type(curr);
    }
    return res.empty() ? "Union" : res;
  }
  case DATA_TYPE_LAMBDA: {
    std::string params;
    for (data_type_node_t *curr = dt_node->data.lambda_type.parameter_types;
         curr != nullptr; curr = curr->next) {
      if (!params.empty()) {
        params += ", ";
      }
      params += format_type(curr);
    }
    return "(" + params + ") => " +
           format_type(dt_node->data.lambda_type.return_type);
  }
  case DATA_TYPE_CURRIED_FUNCTION:
    return "Curried function";
  }

  char *str = nullptr;
  if (type_to_string(dt_node, &str) == NO_ERR && str != nullptr) {
    return std::string(str);
  }

  return "UnknownType";
}

static std::string escape_str(const char *s) {
  if (s == nullptr) {
    return "";
  }
  std::string out;
  for (const char *p = s; (*p) != 0; ++p) {
    switch (*p) {
    case '\n':
      out += "\\n";
      break;
    case '\t':
      out += "\\t";
      break;
    case '\r':
      out += "\\r";
      break;
    case '"':
      out += "\\\"";
      break;
    default:
      out += *p;
      break;
    }
  }
  return out;
}

static void print_ast_list(FILE *out, ast_node_t *head,
                           const std::string &prefix,
                           const char *label = nullptr);

static void print_ast_node(FILE *out, ast_node_t *node,
                           const std::string &prefix, bool is_last,
                           const char *label = nullptr) {
  if (node == nullptr) {
    return;
  }

  std::fprintf(out, "%s%s", prefix.c_str(), is_last ? "└── " : "├── ");
  if ((label != nullptr) && label[0] != '\0') {
    std::fprintf(out, "[%s] ", label);
  }

  std::string child_prefix = prefix + (is_last ? "    " : "│   ");
  // Always print node->data_type so null -> resolved type mutations show up
  // in diff
  std::string node_dt =
      " <node->data_type: " + format_type(node->data_type) + ">";

  switch (node->type) {
  case AST_FUNCTION_DECLARATION:
    std::fprintf(
        out, "FunctionDecl: %s%s (return_type: %s)%s\n",
        node->data.function_declaration.is_main ? "@main " : "",
        (node->data.function_declaration.name != nullptr)
            ? node->data.function_declaration.name
            : "<anon>",
        format_type(node->data.function_declaration.return_type).c_str(),
        node_dt.c_str());
    print_ast_list(out, node->data.function_declaration.parameter_lists,
                   child_prefix, "param_lists");
    print_ast_list(out, node->data.function_declaration.body, child_prefix,
                   "body");
    break;

  case AST_BUILTIN_BODY:
    std::fprintf(out, "Builtin_body");
    break;

  case AST_FUNCTION_CALL:
    std::fprintf(
        out, "FunctionCall: %s() (calling=%s)%s\n",
        (node->data.function_call.name != nullptr)
            ? node->data.function_call.name
            : "<anon>",
        ((node->data.function_call.calling != nullptr) &&
         node->data.function_call.calling->type == AST_FUNCTION_DECLARATION &&
         (node->data.function_call.calling->data.function_declaration.name !=
          nullptr))
            ? node->data.function_call.calling->data.function_declaration.name
            : ((node->data.function_call.calling != nullptr) ? "<resolved>"
                                                             : "null"),
        node_dt.c_str());
    print_ast_list(out, node->data.function_call.argument_lists, child_prefix,
                   "arg_lists");
    break;

  case AST_DOT_FUNCTION_CALL:
    std::fprintf(out, "DotFunctionCall: .%s() (calling=%s)%s\n",
                 (node->data.dot_function_call.name != nullptr)
                     ? node->data.dot_function_call.name
                     : "<anon>",
                 (node->data.dot_function_call.calling != nullptr)
                     ? "<resolved>"
                     : "null",
                 node_dt.c_str());
    print_ast_list(out, node->data.dot_function_call.target, child_prefix,
                   "target");
    print_ast_list(out, node->data.dot_function_call.argument_lists,
                   child_prefix, "arg_lists");
    break;

  case AST_ARGUMENT_LIST:
    std::fprintf(out, "ArgumentList%s\n", node_dt.c_str());
    print_ast_list(out, node->data.argument_list.arguments, child_prefix,
                   "arg");
    break;

  case AST_LAMBDA_DECLARATION:
    std::fprintf(out, "LambdaDecl %s\n", node_dt.c_str());
    print_ast_list(out, node->data.lambda_declaration.parameters, child_prefix,
                   "params");
    print_ast_list(out, node->data.lambda_declaration.body, child_prefix,
                   "body");
    break;

  case AST_PARAMETER_LIST:
    std::fprintf(out, "ParameterList%s\n", node_dt.c_str());
    print_ast_list(out, node->data.parameter_list.parameters, child_prefix,
                   "param");
    break;

  case AST_PARAMETER:
    std::fprintf(
        out, "Parameter: %s%s (param_type: %s)%s\n",
        (node->data.parameter.name != nullptr) ? node->data.parameter.name
                                               : "<anon>",
        node->data.parameter.optional ? "?" : "",
        format_type(node->data.parameter.data_type).c_str(), node_dt.c_str());
    break;

  case AST_CLASS_DECLARATION:
    std::fprintf(out, "ClassDecl: %s%s\n",
                 (node->data.class_declaration.name != nullptr)
                     ? node->data.class_declaration.name
                     : "<anon>",
                 node_dt.c_str());
    print_ast_list(out, node->data.class_declaration.attribute_list,
                   child_prefix, "attr");
    break;

  case AST_TYPE_DECLARATION:
    std::fprintf(out, "TypeDecl: %s = %s%s\n",
                 (node->data.type_declaration.name != nullptr)
                     ? node->data.type_declaration.name
                     : "<anon>",
                 format_type(node->data.type_declaration.data_type).c_str(),
                 node_dt.c_str());
    break;

  case AST_EXTENSION_DECLARATION:
    std::fprintf(out, "ExtensionDecl%s\n", node_dt.c_str());
    print_ast_list(out, node->data.extension_declaration.parameter,
                   child_prefix, "target_param");
    print_ast_list(out, node->data.extension_declaration.function_declarations,
                   child_prefix, "methods");
    break;

  case AST_BLOCK:
    std::fprintf(out, "Block%s\n", node_dt.c_str());
    print_ast_list(out, node->data.block.statement, child_prefix);
    break;

  case AST_VARIABLE_DECLARATION:
    std::fprintf(out, "VarDecl (%s): %s (decl_type: %s)%s\n",
                 node->data.variable_declaration.is_const ? "val" : "var",
                 (node->data.variable_declaration.name != nullptr)
                     ? node->data.variable_declaration.name
                     : "<anon>",
                 format_type(node->data.variable_declaration.data_type).c_str(),
                 node_dt.c_str());
    print_ast_list(out, node->data.variable_declaration.expression,
                   child_prefix, "init");
    break;

  case AST_ASSIGNMENT:
    std::fprintf(out, "Assignment: %s =%s\n",
                 (node->data.assignment.name != nullptr)
                     ? node->data.assignment.name
                     : "<anon>",
                 node_dt.c_str());
    print_ast_list(out, node->data.assignment.expression, child_prefix,
                   "value");
    break;

  case AST_IF:
    std::fprintf(out, "If%s\n", node_dt.c_str());
    print_ast_list(out, node->data.if_statement.condition, child_prefix,
                   "cond");
    print_ast_list(out, node->data.if_statement.true_branch, child_prefix,
                   "then");
    print_ast_list(out, node->data.if_statement.false_branch, child_prefix,
                   "else");
    break;

  case AST_WHILE_DO:
    std::fprintf(out, "WhileDo%s\n", node_dt.c_str());
    print_ast_list(out, node->data.while_do.condition, child_prefix, "cond");
    print_ast_list(out, node->data.while_do.body, child_prefix, "body");
    break;

  case AST_FOR_DO:
    std::fprintf(out, "ForDo%s\n", node_dt.c_str());
    print_ast_list(out, node->data.for_do.iterator, child_prefix, "iter");
    print_ast_list(out, node->data.for_do.generator, child_prefix, "gen");
    print_ast_list(out, node->data.for_do.guards, child_prefix, "guard");
    print_ast_list(out, node->data.for_do.body, child_prefix, "body");
    break;

  case AST_RETURN:
    std::fprintf(out, "Return (discard=%s)%s\n",
                 node->data.return_statement.discard ? "true" : "false",
                 node_dt.c_str());
    print_ast_list(out, node->data.return_statement.expression, child_prefix,
                   "expr");
    break;

  case AST_MATCH:
    std::fprintf(out, "Match%s\n", node_dt.c_str());
    print_ast_list(out, node->data.match.expression, child_prefix, "expr");
    print_ast_list(out, node->data.match.cases, child_prefix, "case");
    break;

  case AST_MATCH_CASE:
    std::fprintf(out, "MatchCase%s\n", node_dt.c_str());
    print_ast_list(out, node->data.match_case.pattern, child_prefix, "pattern");
    print_ast_list(out, node->data.match_case.guard, child_prefix, "guard");
    print_ast_list(out, node->data.match_case.block, child_prefix, "block");
    break;

  case AST_BINARY_OPERATION:
    std::fprintf(out, "BinaryOp: '%s'%s\n",
                 op_to_str(node->data.binary_operation.op), node_dt.c_str());
    print_ast_list(out, node->data.binary_operation.left, child_prefix, "left");
    print_ast_list(out, node->data.binary_operation.right, child_prefix,
                   "right");
    break;

  case AST_UNARY_OPERATION:
    std::fprintf(out, "UnaryOp: '%s'%s\n",
                 op_to_str(node->data.unary_operation.op), node_dt.c_str());
    print_ast_list(out, node->data.unary_operation.expression, child_prefix,
                   "expr");
    break;

  case AST_IDENTIFIER:
    std::fprintf(out, "Identifier: %s%s\n",
                 (node->data.identifier.name != nullptr)
                     ? node->data.identifier.name
                     : "<anon>",
                 node_dt.c_str());
    break;

  case AST_LITERAL:
    std::fprintf(out, "Literal (lit_type: %s): \"%s\"%s\n",
                 format_type(node->data.literal.data_type).c_str(),
                 escape_str(node->data.literal.raw).c_str(), node_dt.c_str());
    break;

  case AST_INTERPOLATED_STRING:
    std::fprintf(out, "InterpolatedString%s\n", node_dt.c_str());
    print_ast_list(out, node->data.interpolated_string.expressions,
                   child_prefix, "part");
    break;

  case AST_LIST_CONSTRUCTOR:
    std::fprintf(out, "ListConstructor%s\n", node_dt.c_str());
    break;
  }
}

static void print_ast_list(FILE *out, ast_node_t *head,
                           const std::string &prefix, const char *label) {
  for (ast_node_t *curr = head; curr != nullptr; curr = curr->next) {
    print_ast_node(out, curr, prefix, curr->next == nullptr, label);
  }
}

#pragma endregion

void dump_ast_to_file(const char *filepath, ast_node_t *root) {
  FILE *file = std::fopen(filepath, "w");
  ASSERT_NE(file, nullptr) << "Failed to open file: " << filepath;
  if (root == nullptr) {
    std::fprintf(file, "(empty AST)\n");
  } else {
    print_ast_list(file, root, "");
  }
  std::fclose(file);
}